def atbash_cipher(s):
    out = []
    for ch in s:
        if ch.isupper():
            out.append(chr(ord('Z') - (ord(ch) - ord('A'))))
        elif ch.islower():
            out.append(chr(ord('z') - (ord(ch) - ord('a'))))
        else:
            out.append(ch)
    return ''.join(out)

def replace_digits_with_words(s):
    names = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]
