def reorder_by_priority_with_fallback_alpha(items, priority):
    pos = {v: i for i, v in enumerate(priority)}
    listed = [x for x in items if x in pos]
    listed.sort(key=lambda x: pos[x])
    unlisted = sorted(x for x in items if x not in pos)
    return listed + unlisted

def convert_between_timezones(time_str, from_offset_min, to_offset_min):
    hh, mm = map(int, time_str.split(":"))
    total = hh * 60 + mm - from_offset_min + to_offset_min
    day_delta = total // 1440
    rem = total % 1440
    return (f"{rem // 60:02d}:{rem % 60:02d}", day_delta)

