def tokenize_mixed_alnum(s):
    tokens = []
    current = ""
    current_type = None
    for c in s:
        if c.isalpha():
            ctype = 'alpha'
        elif c.isdigit():
            ctype = 'digit'
        else:
            ctype = None
        if ctype is None:
            if current:
                tokens.append(current)
                current = ""
                current_type = None
            continue
        if ctype == current_type:
            current += c
        else:
            if current:
                tokens.append(current)
            current = c
            current_type = ctype
    if current:
        tokens.append(current)
    return tokens

